INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter20-libraries', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter20-libraries-p1", "partName": "Origins and Significance of the Library Movement", "bodyMd": "The library movement was old in the Andhra region generally, and it began in Telangana in the early twentieth century just as it did in other parts of the country. From its earliest days, the library movement played an outstanding role in Andhra national life.\n\n*   Suravaram Pratap Reddy called the Library Movement the **first movement** in Telangana.\n*   **Father of the Telangana library movement:** Komarraju Lakshmana Rao.\n*   Libraries gave the public access to newspapers and books, and served as venues for meetings, poetry gatherings, and various organisations'' anniversary celebrations. They brought political and literary writing within easy reach of students and townspeople, feeding the public''s thirst for knowledge.\n*   It was largely through libraries that national consciousness took root in Telangana, and it was through libraries that the Andhra Movement (Andhrodyamam) spread rapidly across the state.\n\n| Library | Year | Founder(s) | Notes |\n|---|---|---|---|\n| Secunderabad Library | 1872 | Somasundar Mudaliyar | First library in Hyderabad and Telugu-speaking regions; merged with Mahbubia College in 1884 |\n| Shankarananda Library (Shankarmatt) & Sarvajanika Library (Secunderabad) | 1872 | Mudigonda Shankaracharyulu | — |\n| Young Men''s Improvement Society Library | 1879 | Aghoranath Chattopadhyaya | — |\n| Asafiya State Library | 1886 | Abdul Khayyum (nationalist), Moulvi Sayyad Hussain Bilgrami (Nawab), and Imadul Mulk | Established for public use; today known as the **State Central Library**, located in the Afzalgunj area |\n| Bharat Gunavardhak Association Library | 1895 | Established by Marathi patriots at Shalibanda (Laldarwaza area) | For the development of Marathi language and culture; holds rare compositions of ancient poets and books in many languages, and is still functioning |\n| Albert Reading Room (Bollarum) | 1896 | — | — |", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter20-libraries-p2", "partName": "Sri Krishna Devaraya Andhra Basha Nilayam (1901) — The Movement''s First Library", "bodyMd": "Sri Krishna Devaraya Andhra Basha Nilayam was established at Sultan Bazar, Hyderabad, in 1901 by **Komarraju Lakshmana Rao**, in the personal house of Ravichettu Ranga Rao.\n\n*   **Founders/supporters:** Munagala zamindar Raja Nayini Venkata Ranga Rao and Ravichettu Ranga Rao.\n*   **Aims:** to adorn the Telugu mother tongue with a golden crown, eradicate illiteracy, promote historical research, and stand in opposition to the Nizam''s suppressive policies.\n*   It was the **first library established as part of Telangana''s library movement**.\n*   **Literary festivals organised by this library:**\n    *   Pothana Death Anniversary Week — 1940\n    *   Reddy Yuga Saraswatha Week — 1941\n    *   Bhuvana Vijaya Week — 1942\n    *   Ramayana Kalpa Vruksha Week — 1950", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter20-libraries-p3", "partName": "Libraries Founded by Komarraju Lakshmana Rao and Other Early Libraries (1901–1908)", "bodyMd": "Lakshmana Rao went on to found a cluster of libraries across the region:\n\n*   **Sri Raja Raja Narendra Andhra Basha Nilayam** — Hanumakonda, 1904.\n*   **Andhra Samvardhani Library** — Secunderabad, 1905.\n*   **Vignana Chandrika Mandali** — Hyderabad, 1906. Ravichettu Ranga Rao served as its secretary. Its headquarters were at Rasidenchi Bazar, in Ravichettu Ranga Rao''s own house. It conducted novel-writing competitions and Telugu-language examinations, and published books on history, Andhra literature, and science (Vignana Shastram). The Nizam''s police kept close watch on Ravichettu''s activities, and the Mandali''s office eventually had to be shifted to Madras.\n    *   **Books published by Vignana Chandrika Mandali:** Chilkuri Veera Bhadra Rao — _Andhrula Charitra_; Gadicherla Hari Sarvothama Rao — _Abraham Lincoln History_; Achanta Lakshmipathi — _Jeeva Shastram (Biology)_; Suravaram Pratap Reddy — _Andhrula Sangika Charitra_; Khandavalli Lakshmi Rajanam — _Andhrula Charitra-Samskruthi_; Kattamanchi Ramalinga Reddy — _Arthashastra, Musalamma Maranam_; Vishwanadha Sharma — _Chemistry_.\n\nSeparately, the effort of Munagala Raja Nayini Venkata Ranga Rao, Komarraju Lakshmana Rao, Gadicherla Harisarvottama Rao, and Ayyadevara Kaleswara Rao also brought about the **Vignana Niketana Grandhalayam** in Khammam, realised through Kodati Narayana Rao''s persistent effort.\n\nSeparately, Hanumakonda''s **Rajarajanarendra Andhra Basha Nilayam**, established in 1908, counted **\"Andhra Pitamaha\" Madapati Hanumantha Rao** among its secretaries.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter20-libraries-p4", "partName": "Reddy Hostel Library (1918) and Suravaram Pratap Reddy", "bodyMd": "*   In 1918, **Raja Bahadur Venkat Rami Reddy** established Reddy Hostel in Abids, Hyderabad, to provide accommodation for students. The Reddy Hostel Library was set up within its premises.\n*   From 1924–32, **Suravaram Pratap Reddy** served as Secretary of the Reddy Hostel Library.\n*   Suravaram wrote a book, _Telangana-Andhrula Kartavyam_, on the maintenance of libraries and the duties of those in the library movement.\n*   The Nizam government had banned Veer Savarkar''s _War of Independence_, and when a copy of this banned book was found in the Reddy Hostel Library, Suravaram lost his position as secretary as a result.\n*   Other key figures of the movement alongside Komarraju Lakshmana Rao: **Somanatha Rao** and **Kodati Narayana Rao** (whose autobiography, _Narayanatrayam_, records the library movement).", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter20-libraries-p5", "partName": "Other Libraries Founded Across Telangana", "bodyMd": "| Library | Year | Place | Founder |\n|---|---|---|---|\n| Andhra Basha Nilayam | 1910 | Khammam | — |\n| Pratapa Rudra Andhra Basha Nilayam | 1913 | Madikonda, Warangal | — |\n| Samskruta Kala Vardhini | 1913 | Secunderabad | — |\n| Andhra Vignana Prakashini | 1918 | Suryapet | Puvvada Venkatapayya (also founded _Krushi Pracharini Grandhamala_ and printed Telugu books; dismissed from his government job by the Nizam administration for this) |\n| Andhra Saraswaati Library | 1918 | Nalgonda | Shabnavisu Venkata Rama Narasimha Rao |\n| Basha Kalpavalli Library | 1920 | Secunderabad | Maduri Raghavulu |\n| Sri Vignana Vidhyuth Pravahini Andhra Basha Nilayam | 1918 | Khammam | Published a monthly magazine, _Jyothi_, edited by Yellapragada Krishnamurthy and Kodati Narayana Rao; later converted into a students'' library |\n| Vignana Pracharini Printing Press | 1919 | Inugurthi, Mahabubabad | Oddiraju brothers |\n| Bahiramiya Library | 1921 | Kolanupaka | — |\n| Bala Saraswathi Library | 1923 | Afzalgunj | — |\n| Vemana Andhra Basha Nilayam | 1923 | Hyderabad | Konda Venkat Ranga Reddy (funded from his own money) |\n| Vignana Pracharini Library (also called Osmania Andhra Basha Nilayam) | 1923 | Manthanni | Avadhani Krishnaiah |\n| Andhra Student Association Library | 1923 | Khammam | — |\n| Andhra Sodari Samaja Grandhalayam | 1925 | Hyderabad | — |\n| Adi Hindu Library | 1926 | Hyderabad | B. S. Venkat Rao |\n| Deccan Vaishya Sanga Grandhalayam | 1926 | — | — |\n| Jogipet Library | 1930 | Medak | — |\n| Vidyabi Vardhini Grandhalayam | 1939 | Tatapalli, Karimnagar | Boinpally Venkat Rama Rao (also set up a mobile library, a Harijan school, and a collection of Oriental manuscripts) |\n| Gandhi Library | 1940 | Hanumakonda | Bandari Naga Bhushan Rao |\n| Raithu Grandhalayam | 1941 | Chilukuru | Raavi Narayana Reddy |\n| Sri Hanumadaandhra Grandhalayam | 1943 | Mulkapalli, Khammam | Established by Andhra Sarasvatha Parishad |\n| Viveka Vikasini Grandhalayam | 1943 | Pillalamarri, Suryapet | Ummethula Ramanuja Rao |\n\nBy 1922, on the eve of the Andhra Movement gathering pace in Telangana, roughly **fifteen libraries** had already been established, including the Sabdanusasana Grandhalayam (Warangal), Gyana Vidyut Pravahini Basha Nilayam (Khammam), Mahaboobia Grandhalayam (Errupalem), Siddhi Maleswara Grandhalayam (Remidicherla), Andhra Saraswathi Grandha Nilayam (Nalgonda), Balasaraswathi Andhra Grandhalayam (Golconda Gadda, Hyderabad), and Vemana Andhra Basha Nilayam (Nampalli).", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter20-libraries-p6", "partName": "Innovations in Reaching the Public", "bodyMd": "**Telangana''s first mobile library — T. K. Balaiah**\n\n*   T. K. Balaiah, a taluka officer at Armoor in Nizamabad district, started Telangana''s first mobile library, carrying books by bullock cart to remote villages and distributing them there.\n\n**Korutla''s rice-for-books model**\n\n*   At Korutla in Karimnagar district, Satavadhani Krishnamacharyulu went door to door collecting rice, sold the rice he had gathered, and used the proceeds to buy books and periodicals. Library workers also toured on cycles to distribute books — an early form of the \"travelling library.\"\n\n**Arjun Pusthaka Bandagar (Suryapet)**\n\n*   Established and secretly run by Dharma Biksham, Kannaiah, and their friends, this book depot supplied Arya Samaj literature and the _Golconda_, _Mejaan_, and _Raiyat_ newspapers, and became a centre for political and literary discussion.\n\n**The Chennur \"feast\" library (Adilabad district)**\n\n*   Chennur''s Brahmin-majority public loved ceremonial feasts but would not come forward to fund a library. A Maharashtrian doctor at the government hospital, understanding this, announced that he wished to host a _samaradhana_ (ceremonial feast) and asked the village for the needed items — rice, jaggery, betel nut, coconut, dry fruit, vermicelli, and more — which poured in generously, since everyone was eager to meet a doctor''s request but too polite to ask about his fee directly.\n*   The doctor then sold off the surplus feast provisions the next day for about three thousand rupees, used the money to buy roughly three hundred _gajas_ of land at the village centre, put up a tin shed, and bought petromax lamps and books, naming the result the **\"Godavari Vachanalayam.\"** He then told the village elders that the library had been built from what remained of the feast they themselves had funded. More libraries followed in Adilabad town after this.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter20-libraries-p7", "partName": "Obstacles Faced by the Library Movement", "bodyMd": "Running a library under Nizam rule was far from easy, and the movement''s workers faced repeated official harassment:\n\n1.  **Suryapet — Andhra Prakasini Grandhalayam seized.** Just as the Andhra Movement was about to gather pace, the local collector abruptly sealed this library, treating its public-funded, community-run operation as an act of overreach by its officer-in-charge, and demanding to know whether government permission had been obtained to run it.\n    *   When the workers said no, the collector ordered the library shut.\n    *   The matter was carried to Madapati Hanumantha Rao''s group in Hyderabad, who wrote to the government''s Home Secretary, Sir Akbar Hyderi (also chairman of the district local fund board, from which libraries were known to receive grants).\n    *   The Home Secretary confirmed no government permission was required to run a library, and the library reopened.\n2.  **Madikonda library** was similarly denied permission to operate for a full year.\n3.  **Karimnagar district (Sirisilla)** — when a visiting tahsildar inspected the library there, he reportedly remarked that government business was conducted entirely in Urdu and there was no need to \"accumulate dead Telugu-language books\" — reflecting the intense official hostility toward Telugu at the time, despite it being the majority language of the state.\n4.  **Chasing funds:** since no one came forward to donate or pay subscriptions, village elders and enthusiasts had to raise money creatively — selling collected goods, books, newspapers, and furniture — to keep libraries running.\n5.  **Nalgonda and Suryapet anniversary celebrations:** the district collector tried to impose a condition that all lecture content be submitted to him for prior approval. Library workers refused this humiliating demand, and even under an ensuing policy of non-cooperation from the administration, their enthusiasm did not wane.\n    *   **Outcome:** the High Court eventually ruled that the government had no authority to disperse such meetings — a landmark moment in the history of the movement.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter20-libraries-p8", "partName": "Ana Grandhamala and Deshoddaraka Grandhamala — Cheap Books for Mass Circulation", "bodyMd": "Founded in 1939 by **Vellutri Manikya Rao** and **Gundavarapu Hanumantha Rao**, with the support of **K. C. Gupta** \n\n*   The scheme was to price books at one anna each, offering roughly a hundred books for just five rupees. Gupta''s house served as the series'' distribution centre, and copies were sold in front of Subbarao''s Hotel in Golconda and in Sultan Bazar, Hyderabad.\n*   **First publication (November 1939):** _Hyderabad Rajyanga Samskaranalu_ (Hyderabad Constitutional Reforms) — a Telugu translation, by Vellutri Manikya Rao, of a Nizam-government-confiscated edition originally in Urdu, with a foreword by Madapati Hanumantha Rao. It went through two reprints without meeting demand.\n*   Vellutri Manikya Rao then published **\"Raithu\" (Ryot)**, urging farmers to unite and detailing their grievances — this book was **banned by the Nizam government**.\n*   To catch those distributing Ana Grandhamala titles, the Nizam''s administration posted police watch outside two hotels — a measure of how seriously the regime feared this cheap-book campaign.\n*   In 1943, Ana Grandhamala also published stories by **Kaloji Narayan Rao**: _Maname Nayam_ (\"We Are Better,\" on cruelty to animals), _Teliyaka Prema Telisi Dwesham_ (\"Love Without Knowledge, Hatred With Knowledge,\" on caste discrimination), and _Vibhuthi_ (a critique of modernisation).\n\nVattikota Alwar Swamy established the **Deshoddaraka Grandhamala** in 1938, with a publishing span across **1938–41 and 1953–61**.\n\n*   **Publications:** Kaloji Narayana Rao — _Naa Godava_ (Poems); Suravaram Pratap Reddy — _Prajadikaramulu_.\n*   Over this period Vattikota personally distributed around thirty books, slinging a bag over his shoulder and selling them not for profit — charging just ten rupees for books worth four times as much.\n*   This practice sparked a culture of reading and book circulation, and works illuminating Telangana''s history and culture while addressing contemporary problems helped awaken both literary spirit and politi' WHERE chapter_slug = 'telangana-history-en-chapter20-libraries';
UPDATE theory_content SET concepts_json = concepts_json || 'cal consciousness across the region.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter20-libraries-p9", "partName": "Telangana Literary Organisations", "bodyMd": "*   In 1934, **Suravaram Pratap Reddy** compiled the works of **354 Telangana poets** across the region''s four districts into the _Golconda Kavula Sanchika_ — a landmark work of self-respect for Telangana.\n    *   **Background:** some had claimed that Telugu was spoken only in Telangana''s villages and that its towns had no poets of note — a claim that deeply hurt Suravaram and drove him to compile this anthology in response.\n*   In 1911, **Chandala Kesavadasu** wrote the drama _Kanaka Tara_, which became a foundation for modern Telugu drama.\n*   **Kodati Narayana Rao** ran the _Pragathi_ and _Bala Saraswati_ newspapers.\n*   **Ratnamamba Desai** wrote poems in the _Hithabodhini_ newspaper encouraging women''s education.\n*   **Pasham Narayan Reddy''s** literary works include _Life History of Dayananda Saraswati_, _Thayaga Murthulu_, and _Sadashiva Reddy_ (on the Papannapet ruler who opposed the Nizam out of loyalty/friendship).\n*   Telangana was, in any case, home to a long medieval poetic tradition — **Pothana, Palkuriki Somanadha, Pillalamarri Pinaveerabhadrudu, Vemulawada Bhimakavi, Mallinatha Suri, Anantudu**, and **Vidyanadhudu** were all born and raised in this region.\n\n### Literary Bodies\n\n**Sahiti Mekala (1936)** — Telangana''s first literary organisation, started in Nalgonda by **Ambatipudi Venkat Ratna Shastri**.\n\n*   Books published: Dasharathi Krishnamacharyulu — _Agnidhara_; Ambatipudi Venkat Ratnam — _Tarka Basha_; Punna Anjaiah — _Nilgiri Kavulu Sanchika_; Pulijala Gopal Rao — _Kadga Tikkana_.\n\n**Hyderabad Sahitya Parishad (1932)** — founded with **Acharya Rayaprolu Subbarao** as president and **Acharya Kurugganti Seetharamayya** as secretary.\n\n**Sadhana Samithi (1939)** — key founders included **Burgula Ranganatha Rao**, **Bhaskarbattla Krishna Rao**, and **Veldurthi Manikya Rao**\n\n*   Books published: Devulapalli Ramanuja Rao — _Navya Kavitha Nirajanam_ (Essays); Burgula Ranganatha Rao — _Vahyali_ (Stories); Bogi Narayana Murthy — _Pariksha–Chaduvu_ (Drama); Gadiraju Venkata Ramanaiah — _Bojaraju_ (Poem).\n*   Members read their new compositions aloud at the Samithi''s gatherings.\n\n**Viveka Vardhini Parishad (1941)** — established by Suravaram Pratap Reddy, publishing his own works _Ramayana Visheshalu_, _Mruthyu Siddantham_, and _Andhra Prataprudra Yashobhushanam_.\n\n**Other named literary organisations:** Navya Sahithi Samithi (Raavi Narayana Reddy) and Vaithalika Samithi (Kaloji Narayana Rao).\n\n**Vignana Chandrika Grandhamala at Nemalikonda** — established by well-known writers in Jagtial taluka''s Nemalikonda village, publishing four valuable books on village agriculture, medicine, industry, and historical subjects.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-chapter20-libraries-p10", "partName": "Andhra Saraswatha Parishad", "bodyMd": "In the context of the 10th Andhra Mahasabha, **Vattikota Alwar Swamy** initiated an early effort with support from **Burgula Ranganatha Rao** and **Bhaskarabhatla Krishna Rao**, assembling Hyderabad''s leaders and regional literary figures at the Reddy Hostel library building on **26 May 1943**, with **Lokanandi Shankaranarayana Rao** presiding. It was unanimously decided to establish a single literary organisation dedicated to promoting Andhra language and culture.\n\n*   Disputes arose over what to name the new body; as a stop-gap, **Rayaprolu Subbarao, Mahammad Khasim Khan,** and **Kurugganti Seetharamayya (Rahasi)** jointly set up a token organisation called the **\"Hyderabad Andhra Sahitya Parishad\"** while the naming question was settled\n*   With government cooperation, the organisation published its own books as well as books praising the Nizam Nawab, and it was accordingly decided to name the body the **\"Nizam Rashtra Andhra Saraswatha Parishat.\"**\n*   An eleven-member subcommittee was chosen to draft rules and a working plan: Madapati Hanumantha Rao, Bukkapatnam Ramanujacharyulu, Suravaram Pratap Reddy, Lokanandi Shankaranarayana Rao, Burgula Ramakrishna Rao, Chidiremarthi Veerabhadra Sarma, Adiraju Veerabhadra Rao, Nandagiri Venkata Rao, Kodati Narayana Rao, Gadiyaram Ramakrishna Sarma, and Bhaskarabhatla Krishna Rao.\n\n**First Mahasabha (1 June 1943, Reddy Hostel Library):**\n\n*   **President:** Lokanandi Shankaranarayana Rao\n*   **Chief secretary:** Bidudu Venkata Seshaiah\n*   The organisation''s headquarters was initially the _Golconda_ newspaper office; when Lokanandi took up a government job and had to leave the city, **Suravaram Pratap Reddy** became president.\n*   **1949:** the words \"Nizam Rashtra\" were dropped from the name, leaving it simply **Andhra Saraswatha Parishad**.\n\n**Objectives:** (1) foster respect for the mother tongue; (2) reward outstanding literary work; (3) raise literacy by running night schools in villages.\n\n**Published book series:** _Panditha Saraswatham_, _Praja Saraswatham_, and _Bala Saraswatham_, alongside the newspaper _Andhra Sri_.\n\n| Series | Authors and works |\n|---|---|\n| Panditha Saraswatham | Suryanarayana Shastri — _Kavyalankarana Sangraham_; Burgula Ramakrishna Rao — _Saraswatha Vyasa Mukthavalli_; Divakarla Venkata Avadhani — _Sahitya Sopanalu_, _Andhra Vagmaya Charitra_; Rallapalli Anantha Krishna Shastri — _Shalivahana Gadha_, _Saptha Shathisaram_ |\n| Praja Saraswatham | Suravaram Pratap Reddy — _Andhrula Sanghika Charitra_; Nelaturi Venkaiah — _Andhrula Charitra_; Krishna Shastri — _Pallepadalu_, _Streela Pouranika Patalu_ |\n| Bala Saraswatham | Devulapalli Ramanuja Rao — _Mana Desham_; Gadiyaram Ramakrishna Sharma — _Veera Gadhalu_; Adiraju Veera Bhadra Rao — _Mithai Chettu_ |\n\n**Second Anniversary (Warangal):**\n\n*   **President:** Udayaraju Rajeshwara Rao; **secretary of the reception committee:** Kaloji Narayana Rao.\n*   The gathering was held in the compound of Rajeshwara Rao''s own bungalow; roughly thirty poets and pandits were served meals in silver vessels as a mark of special hospitality.\n*   Kosthal Venkataramireddy inaugurated proceedings, with Suravaram Pratap Reddy presiding.\n*   Razakar goons destroyed the pandal set up for the morning poet-conference at Warangal Fort, but **M. S. Rajalingam**, with his youth organisation, took charge of the venues and ensured the conference proceeded successfully regardless.\n\n**Third Mahasabha (Nalgonda):** held with much difficulty, presided over by Kanchanapalli China Venkata Rama Rao; amid political instability in the state, meetings closed with little enthusiasm. In the Nizam''s dominions, the Ittehad-ul-Muslimeen could not tolerate the Parishad''s activities, and atrocities followed.\n\n**Mahbubnagar district:** Devulapalli Ramanuja Rao''s friend, collector Illindala Ramachandra Rao, helped arrange Parishad meetings there despite strong opposition from local Muslim hardliners, refusing to let their tactics succeed.\n\n**Impact of 1947–48:** after British India''s independence on 15 August 1947, the Nizam declared Hyderabad independent and the Razakar movement intensified. During this period of lawlessness, Parishad secretary **Biduru Venkateshayya** left the state for a safer region, and the Parishad''s activities were paralysed for a time.\n\n**Overall contribution:** the Andhra Saraswatha Parishad worked toward the all-round development of Andhra culture and literature — eradicating illiteracy, spreading mother-tongue education, holding meetings and conferences, collecting and publishing rare literary material, compiling regional-dialect glossaries, conducting Telugu examinations, encouraging writers, opening branch offices, and publishing quality books. Burgula, Suravaram, Madapati, Chennareddy, and P. V. Raghavacharyulu, among other leaders, were all associated with it, belonging to no single faction. **Devulapalli Ramanuja Rao** played a particularly prominent role in nurturing the organisation, and **Dr. C. Narayana Reddy** later took up this responsibility, building new premises and shaping modern programmes for it.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-chapter20-libraries-p11", "partName": "Preserving Telangana''s Historical Record", "bodyMd": "Doopati Venkataramanacharyulu travelled extensively across his home region, collecting over five thousand palm-leaf manuscripts for copying and preservation, often facing suspicion from villagers reluctant to part with their ancestral texts. Through prolonged research, he established that **Pothana''s birthplace lay in the Warangal region**.\n\nFounded in 1922 by **Adiraju Veerabhadra Rao** as a wing of the Andhra Jana Sangham, dedicated to bringing Telangana''s suppressed history to light. After Adiraju''s death, **Komarraju Lakshmana Rao** headed the council, which published two volumes of _Telangana Sasanalu_ (Telangana Inscriptions).", "free": false}, {"partNumber": 12, "conceptId": "telangana-history-en-chapter20-libraries-p12", "partName": "Nizam Rashtra Grandalaya Mahasabha (Library Conferences)", "bodyMd": "*   **First conference:** held at **Madhira in 1925**, attended by representatives of all libraries in Telangana. **Pingali Venkat Rama Reddy** presided; he also served without salary as a Sessions Judge — a rare achievement, as no Telugu person had held so senior a post at the time. This conference laid the foundation for organised library-building efforts across the Nizam''s dominions.\n*   **Second conference:** held at **Suryapet in 1928**, alongside meetings of the Andhra Jana Sangham. **President:** Vaman Nayak, described as a devoted Maharashtrian patriot. Held together with this library sabha were the Andhra Yuvaka Sabha, Sangha Samskara Sabha, Andhra Mahila Sabha, and Vaishya Yuvajana Sabha — six sabhas over three days as a single festival, whose enthusiasm helped spur the formation of the Andhra Mahasabha.\n*   After the Suryapet gathering, separate library mahasabhas were not organised again; library-movement activity was absorbed into the broader Andhra Mahasabha meetings.", "free": false}, {"partNumber": 13, "conceptId": "telangana-history-en-chapter20-libraries-p13", "partName": "Telangana Rachayitala Sangham and the Poetry Movement in the Freedom Struggle", "bodyMd": "The **Telangana Writers'' Association** was formed in 1952, and from its founding it stirred a wave of literary fervour across Telangana, with writers'' associations springing up in villages everywhere. It gave voice to long-suppressed expression across the region, with **Dasarathi** credited as its most resonant voice. Other members who enriched the association included Acharya Lakshmikanta Ranjanam, C. Narayana Reddy, Kaloji, Vanamamalai, Ramaraju, Palla Durgaiah, Kappagantla Lakshmana Sastry, Irivento Krishnamurthy, and V. P. Raghavacharyulu.\n\nPoetry recitation became an expected feature of library annual functions, school functions, festivals, and poet gatherings, and political mahasabhas were led off by poets'' verses — there was scarcely a place in Telangana without poetry, expressed in the phrase \"in huts, in prisons, in thatched homes, in temple-towered villages.\"\n\n*   The linguistic subjugation imposed by the Nizam''s Hyderabad administration weighed more heavily on Telangana than elsewhere, and the desire for political freedom in turn opened the path to linguistic freedom, fuelling the region''s literary and poetic revival.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter20-libraries';
